.sprotty {
    padding: 0px;
    font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
}

.sprotty-root {
    position: relative;
}

.sprotty-hidden {
    display: block;
    position: absolute;
    width: 0px;
    height: 0px;
}

.sprotty-popup {
    font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
    position: absolute;
    background: white;
    border-radius: 5px;
    border: 1px solid;
    max-width: 400px;
    min-width: 100px;
}

.sprotty-popup > div {
    margin: 10px;
}

.sprotty-popup-closed {
    display: none;
}

.sprotty-projection-bar.horizontal {
    position: absolute;
    width: 100%;
    height: 20px;
    left: 0;
    bottom: 0;
}

.sprotty-projection-bar.vertical {
    position: absolute;
    width: 20px;
    height: 100%;
    right: 0;
    top: 0;
}

.sprotty-viewport {
    z-index: 1;
    border-style: solid;
    border-width: 2px;
}

.sprotty-projection-bar.horizontal .sprotty-projection,
.sprotty-projection-bar.horizontal .sprotty-viewport {
    position: absolute;
    height: 100%;
    top: 0;
}

.sprotty-projection-bar.vertical .sprotty-projection,
.sprotty-projection-bar.vertical .sprotty-viewport {
    position: absolute;
    width: 100%;
    left: 0;
}

@keyframes spin {
	100% {
		transform:rotate(360deg);
	}
}

.animation-spin {
	animation: spin 1.5s linear infinite;
}

.sprotty-missing {
    stroke-width: 1;
    stroke: #f00;
    fill: #f00;
    font-size: 14pt;
    text-anchor: start;
}

.sprotty-junction {
    stroke: #000;
    stroke-width: 1;
    fill: #fff;
