html, body {
    width: 100%;
    height: 100%;
    padding: 0px;
}

.sprotty {
    display: flex;
    height: 100%;
}

.sprotty-hidden {
    height: 0px !important;
}

svg {
    width: 100%;
    flex: 1;
    border-style: none;
    border-width: 0px;
}

svg:focus {
    border-width: 0;
}

.sprotty-status {
    position: absolute;
    top: 5px;
    left: 10px;
    display: flex;
    align-items: center;
}

.sprotty-status .fatal {
    color: var(--vscode-editorError-foreground)
}

.sprotty-status .error {
    color: var(--vscode-editorError-foreground)
}

.sprotty-status .warning {
    color: var(--vscode-editorWarning-foreground)
}

.sprotty-status .info {
    color: var(--vscode-editorInfo-foreground)
}

.sprotty-error {
    fill: var(--vscode-editorError-foreground);
    color: var(--vscode-editorError-foreground);
}

.sprotty-warning {
    fill: var(--vscode-editorWarning-foreground);
    color: var(--vscode-editorWarning-foreground);
}

.sprotty-info {
    fill: var(--vscode-editorInfo-foreground);
    color: var(--vscode-editorInfo-foreground);
}

.sprotty-infoRow .fa {
    margin-right: 8px;
}

.sprotty-status .ok {
    visibility: hidden;
}

.sprotty-status-message {
    visibility: hidden;
    padding-left: 10px;
}

.sprotty-status:hover .sprotty-status-message {
    visibility: visible;
}

.sprotty-popup {
    position: absolute;
    background: #FFE9BE;
    border-radius: 0px;
    border: none;
    max-width: initial;
    min-width: initial;
    z-index: 1;
    padding: 8px;
}

.sprotty-infoRow {
    font-size: small;
    margin-bottom: 8px;
}

.sprotty-infoTitle {
    display: block;
    font-weight: bold;
}
